export const BODY: string = "\n<p>WebP کو PNG میں بدلنا وہ تبدیلی ہے جس میں معیار نہیں گرتا۔ PNG بغیر نقصان کے محفوظ کرتا ہے، اس لیے پکسلز بالکل وہی رہتے ہیں۔</p>\n<p>تبدیلی اس وقت ضروری ہے جب WebP کہیں نہ کھلے، جیسے ڈیزائن سافٹ ویئر، ای میل یا پرانا سسٹم۔ PNG ہر جگہ کھلتا ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ تبدیلی کیسے کریں، شفافیت کیسے بچتی ہے، اور اینیمیٹڈ WebP کا کیا ہوتا ہے۔ تبدیل کرنے کے لیے <a href=\"/ur/webp-ko-png-mein-convert-karein/\">WebP ٹو PNG</a> استعمال کریں۔</p>\n<h2 id=\"what-is-webp-to-png\">WebP ٹو PNG کیا ہے؟</h2>\n<p>WebP ٹو PNG وہ تبدیلی ہے جس میں WebP تصویر کو PNG میں بدلا جاتا ہے۔ یہ تبدیلی معیار نہیں گراتی، کیونکہ PNG بغیر نقصان کے محفوظ کرتا ہے۔</p>\n<p>تبدیلی کا مقصد مطابقت ہے: WebP ہر جگہ نہیں کھلتا، PNG ہر جگہ کھلتا ہے۔ تبدیلی سے تصویر ہر جگہ استعمال ہو سکتی ہے۔</p>\n<p>تبدیلی آسان ہے: فائل اپ لوڈ کریں، PNG چنیں اور ڈاؤن لوڈ کریں۔ سیکنڈوں کا کام ہے۔</p>\n<h2 id=\"is-it-truly-lossless\">کیا یہ واقعی بغیر نقصان کے ہے؟</h2>\n<p>جی ہاں، تبدیلی بغیر نقصان کے ہے۔ PNG ہر پکسل کو بالکل ویسے ہی محفوظ کرتا ہے جیسے وہ WebP میں تھا۔</p>\n<p>بغیر نقصان کے ہونے کی وجہ یہ ہے کہ PNG کمپریشن میں کوئی معلومات نہیں پھینکتا۔ ہر پکسل محفوظ رہتا ہے۔</p>\n<p>لیکن یاد رکھیں: اگر اصل WebP خود نقصان کے ساتھ بنا تھا تو وہ نقصان PNG میں بھی رہے گا۔ PNG پرانا نقصان واپس نہیں لاتا۔</p>\n<h2 id=\"why-png-is-bigger\">PNG بڑا کیوں ہوتا ہے؟</h2>\n<p>PNG بڑا ہوتا ہے کیونکہ وہ بغیر نقصان کے محفوظ کرتا ہے۔ WebP نقصان کے ساتھ کمپریس کرتا ہے، اس لیے چھوٹا ہوتا ہے۔</p>\n<p>PNG کا سائز تصویر پر منحصر ہے: سادہ تصویر کی PNG چھوٹی، پیچیدہ کی بڑی۔ فوٹو کی PNG بہت بڑی ہوتی ہے۔</p>\n<p>PNG بڑا ہونے پر پریشان نہ ہوں۔ یہ تبدیلی کی قیمت ہے: معیار بچتا ہے، سائز بڑھتا ہے۔</p>\n<h2 id=\"transparency-survives\">شفافیت بچتی ہے</h2>\n<p>WebP کی شفافیت PNG میں بچتی ہے، اس لیے شفاف لوگو PNG میں بھی شفاف رہتا ہے۔ یہ لوگو کے لیے بہت اہم ہے۔</p>\n<p>شفافیت جانچنے کے لیے تبدیل شدہ PNG کو رنگین پس منظر پر دیکھیں۔ اگر لوگو کے گرد سفید ڈبہ نہ ہو تو شفافیت بچ گئی ہے۔</p>\n<p>شفافیت کے لیے PNG چنیں، JPG نہیں۔ JPG شفافیت مٹا دیتا ہے۔</p>\n<h2 id=\"no-quality-slider\">کوالٹی سلائیڈر کیوں نہیں؟</h2>\n<p>PNG میں کوالٹی سلائیڈر نہیں ہوتا، کیونکہ PNG بغیر نقصان کے محفوظ کرتا ہے۔ معیار کم کرنے کا کوئی طریقہ نہیں۔</p>\n<p>کوالٹی سلائیڈر صرف JPG اور WebP میں ہوتا ہے، جو نقصان کے ساتھ محفوظ کرتے ہیں۔ PNG میں معیار ہمیشہ مکمل رہتا ہے۔</p>\n<p>اگر PNG بہت بڑا ہو تو اسے کمپریس کریں۔ PNG کمپریشن معیار نہیں گراتی، صرف فائل چھوٹی کرتی ہے۔</p>\n<h2 id=\"animated-webp\">اینیمیٹڈ WebP</h2>\n<p>اینیمیٹڈ WebP کو PNG میں بدلنے پر اینیمیشن ختم ہو جاتی ہے۔ PNG ساکن ہے، اس لیے صرف پہلا فریم بچتا ہے۔</p>\n<p>اینیمیٹڈ WebP کو PNG میں بدلنے سے پہلے سوچیں کہ کیا آپ کو اینیمیشن چاہیے۔ اگر چاہیے تو PNG نہ چنیں۔</p>\n<p>اینیمیٹڈ WebP کا پہلا فریم اکثر بہترین ہوتا ہے، اس لیے PNG میں بدلنے پر وہی ملتا ہے۔</p>\n<h2 id=\"batch-converting\">بیچ میں تبدیلی</h2>\n<p>بیچ میں کئی WebP فائلوں کو ایک ساتھ PNG میں بدلا جا سکتا ہے۔ یہ بہت وقت بچاتا ہے۔</p>\n<p>بیچ میں سب فائلوں کا معیار ایک جیسا رہتا ہے، کیونکہ PNG بغیر نقصان کے محفوظ کرتا ہے۔ بیچ کا نتیجہ ZIP میں ملتا ہے۔</p>\n<p>بیچ سے پہلے ایک فائل آزمائیں۔ اگر وہ صاف ہو تو پوری بیچ بدلیں۔</p>\n<h2 id=\"editing-workflow\">ایڈیٹنگ کا ورک فلو</h2>\n<p>ایڈیٹنگ کا ورک فلو یہ ہے: WebP کو PNG میں بدلیں، PNG کو ایڈٹ کریں، اور حتمی فائل کو WebP میں محفوظ کریں۔ اصل WebP محفوظ رکھیں۔</p>\n<p>ورک فلو میں PNG صرف درمیانی مرحلہ ہے۔ حتمی فائل WebP میں رکھیں، تاکہ وہ چھوٹی رہے۔</p>\n<p>ورک فلو کو لکھ کر دیں، تاکہ ٹیم کے ہر رکن کو معلوم ہو کہ کب کون سا فارمیٹ استعمال کرنا ہے۔</p>\n<h2 id=\"where-png-works\">PNG کہاں کام کرتا ہے</h2>\n<p>PNG ہر جگہ کام کرتا ہے: ڈیزائن سافٹ ویئر، ای میل، پرنٹر، پرانا سسٹم، سوشل میڈیا۔ PNG سب سے محفوظ فارمیٹ ہے۔</p>\n<p>PNG لوگو اور آئیکن کے لیے بہترین ہے، کیونکہ وہ شفافیت بچاتا ہے اور متن تیز رکھتا ہے۔</p>\n<p>PNG فوٹو کے لیے اچھا نہیں، کیونکہ فوٹو کی PNG بہت بڑی ہوتی ہے۔ فوٹو کے لیے JPG چنیں۔</p>\n<h2 id=\"metadata\">میٹا ڈیٹا</h2>\n<p>تبدیلی میں میٹا ڈیٹا، جیسے مقام اور کیمرہ، ہٹ جاتا ہے۔ یہ رازداری کے لیے اچھا ہے۔</p>\n<p>میٹا ڈیٹا ہٹنے سے فائل بھی چھوٹی ہوتی ہے۔ ویب پر میٹا ڈیٹا کی ضرورت نہیں۔</p>\n<p>اگر میٹا ڈیٹا چاہیے تو اصل WebP محفوظ رکھیں۔ PNG نقل میں میٹا ڈیٹا نہیں ہوتا۔</p>\n<h2 id=\"screenshots-with-text\">متن والے اسکرین شاٹ</h2>\n<p>متن والے اسکرین شاٹ کے لیے PNG بہترین ہے، کیونکہ PNG میں متن تیز رہتا ہے۔ WebP میں متن دھندلا ہو سکتا ہے۔</p>\n<p>اسکرین شاٹ کو WebP سے PNG میں بدلنے سے متن صاف ہو جاتا ہے۔ یہ دستاویز کے لیے اہم ہے۔</p>\n<p>اسکرین شاٹ کے لیے PNG کا سائز درست رکھیں۔ بڑا اسکرین شاٹ فائل کو بھاری کر دیتا ہے۔</p>\n<h2 id=\"common-mistakes\">عام غلطیاں</h2>\n<p>سب سے عام غلطی یہ ہے کہ لوگ اصل WebP مٹا دیتے ہیں۔ اصل محفوظ رکھیں، کیونکہ PNG سے WebP واپس نہیں بنتا۔</p>\n<p>دوسری غلطی یہ ہے کہ لوگ PNG کو ویب پر لگا دیتے ہیں۔ ویب کے لیے WebP رکھیں، PNG صرف ایڈیٹنگ کے لیے ہے۔</p>\n<p>تیسری غلطی یہ ہے کہ لوگ فوٹو کو PNG میں بدل دیتے ہیں۔ فوٹو کی PNG بہت بڑی ہوتی ہے، اس لیے فوٹو کے لیے JPG چنیں۔</p>\n<h2 id=\"webp-for-design-work\">ڈیزائن کے کام کے لیے WebP</h2>\n<p>ڈیزائن کے کام کے لیے WebP کو PNG میں بدلنا پڑتا ہے، کیونکہ ڈیزائن سافٹ ویئر WebP نہیں کھولتا۔</p>\n<p>ڈیزائن کے لیے PNG نقل بنائیں اور اصل WebP محفوظ رکھیں۔ ڈیزائن کے بعد حتمی فائل WebP میں محفوظ کریں۔</p>\n<p>ڈیزائن کے کام میں PNG کی شفافیت اہم ہے۔ شفاف PNG ڈیزائن میں درست لگتا ہے۔</p>\n<h2 id=\"webp-for-print\">پرنٹ کے لیے WebP</h2>\n<p>پرنٹ کے لیے WebP نہ بھیجیں، کیونکہ پرنٹر اسے نہیں لیتا۔ پرنٹ کے لیے PNG چنیں۔</p>\n<p>پرنٹ کے لیے PNG کا سائز بڑا رکھیں، تاکہ پرنٹ صاف نکلے۔ چھوٹا PNG پرنٹ میں دھندلا ہو جاتا ہے۔</p>\n<p>پرنٹ سے پہلے PNG کو مکمل سائز میں دیکھیں۔ اگر وہ صاف لگے تو پرنٹ بھی صاف نکلے گا۔</p>\n<h2 id=\"webp-for-office-documents\">دفتری دستاویز کے لیے WebP</h2>\n<p>دفتری دستاویز، جیسے ورڈ یا پاورپوائنٹ، میں WebP اکثر نہیں کھلتا۔ دستاویز کے لیے PNG چنیں۔</p>\n<p>دستاویز میں PNG تصویر ہمیشہ کھلتی ہے۔ WebP تصویر خالی ڈبہ بن جاتی ہے۔</p>\n<p>دستاویز کے لیے تصویر کو PNG میں بدل کر شامل کریں۔ اصل WebP الگ محفوظ رکھیں۔</p>\n<h2 id=\"webp-for-archiving\">محفوظ کرنے کے لیے WebP</h2>\n<p>محفوظ کرنے کے لیے PNG بہتر ہے، کیونکہ وہ بغیر نقصان کے محفوظ کرتا ہے۔ WebP نقصان کے ساتھ محفوظ کرتا ہے۔</p>\n<p>محفوظ کرنے کے لیے اصل WebP اور PNG نقل دونوں رکھیں۔ اصل WebP چھوٹی ہے، PNG نقل مکمل ہے۔</p>\n<p>محفوظ کرنے کے لیے فائل کا نام اور تاریخ لکھیں، تاکہ بعد میں معلوم ہو کہ کون سی فائل کب کی ہے۔</p>\n<h2 id=\"webp-for-client\">گاہک کے لیے WebP</h2>\n<p>گاہک کو تصویر بھیجنے کے لیے PNG چنیں، کیونکہ وہ ہر جگہ کھلتا ہے۔ WebP گاہک کے سسٹم میں نہیں کھل سکتا۔</p>\n<p>گاہک کو PNG بھیجنے سے پہلے اس کا سائز جانچیں۔ بڑی PNG ای میل میں دیر سے جاتی ہے۔</p>\n<p>گاہک کو تصویر بھیجنے کے لیے PNG اور JPG دونوں رکھیں۔ گاہک جو چاہے، وہ کھول سکتا ہے۔ مزید تفصیل <a href=\"/ur/blog/webp-ko-png-mein-kaise-convert-karein/\">WebP کو PNG میں کیسے بدلیں</a> میں اور ایڈیٹنگ کی مطابقت <a href=\"/ur/blog/webp-ko-png-editing-aur-compatibility/\">WebP ٹو PNG ایڈیٹنگ مطابقت</a> میں دیکھیں۔</p>\n";

